package io.github.hienpham0344.stayfinder.review;
import io.github.hienpham0344.stayfinder.review.service.*;import io.github.hienpham0344.stayfinder.review.repository.*;import io.github.hienpham0344.stayfinder.review.mapper.*;import io.github.hienpham0344.stayfinder.review.dto.*;import io.github.hienpham0344.stayfinder.review.entity.*;
import io.github.hienpham0344.stayfinder.booking.service.BookingEligibility;import io.github.hienpham0344.stayfinder.accommodation.service.AccommodationLookup;import io.github.hienpham0344.stayfinder.media.service.MediaService;import io.github.hienpham0344.stayfinder.user.repository.UserRepository;import io.github.hienpham0344.stayfinder.user.entity.User;import io.github.hienpham0344.stayfinder.common.exception.*;
import jakarta.persistence.EntityManager;import org.junit.jupiter.api.*;import org.mapstruct.factory.Mappers;import java.time.*;import java.util.*;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class ReviewServiceTest{
 ReviewRepository rows;BookingEligibility eligibility;MediaService media;UserRepository users;ReviewServiceImpl service;UUID owner=UUID.randomUUID(),stay=UUID.randomUUID(),booking=UUID.randomUUID();Clock clock=Clock.fixed(Instant.parse("2026-10-13T12:00:00Z"),ZoneOffset.UTC);
 @BeforeEach void setup(){rows=mock(ReviewRepository.class);eligibility=mock(BookingEligibility.class);media=mock(MediaService.class);users=mock(UserRepository.class);service=new ReviewServiceImpl(rows,eligibility,accommodationLookup(),Mappers.getMapper(ReviewMapper.class),media,users,mock(EntityManager.class),clock);var author=new User();author.setId(owner);author.setFullName("Synthetic author");when(users.findById(owner)).thenReturn(Optional.of(author));when(rows.saveAndFlush(any())).thenAnswer(i->i.getArgument(0));when(media.reviewUrls(any())).thenReturn(List.of());}
 AccommodationLookup accommodationLookup(){var a=mock(AccommodationLookup.class);when(a.findBookingView(stay)).thenReturn(Optional.of(mock(io.github.hienpham0344.stayfinder.accommodation.service.AccommodationBookingView.class)));return a;}
 @Test void creationRequiresPaidCompletedOwnedSourceBooking(){when(eligibility.hasCompletedBookingForAccommodation(owner,booking,stay)).thenReturn(false);var e=assertThrows(BusinessException.class,()->service.create(owner,stay,new CreateReviewRequest(booking,5,"Good",List.of())));assertEquals(ErrorCode.REVIEW_NOT_ELIGIBLE,e.getErrorCode());verify(rows,never()).saveAndFlush(any());}
 @Test void duplicateIsConflictAndValidCreationUsesClockAndOwnedMedia(){when(eligibility.hasCompletedBookingForAccommodation(owner,booking,stay)).thenReturn(true);var existing=new Review();when(rows.findByBookingIdAndUserId(booking,owner)).thenReturn(Optional.of(existing));assertEquals(ErrorCode.DUPLICATE_RESOURCE,assertThrows(BusinessException.class,()->service.create(owner,stay,new CreateReviewRequest(booking,5,"Good",List.of()))).getErrorCode());when(rows.findByBookingIdAndUserId(booking,owner)).thenReturn(Optional.empty());var image=UUID.randomUUID();var result=service.create(owner,stay,new CreateReviewRequest(booking,4," Good ",List.of(image)));assertEquals(clock.instant(),result.createdAt());assertEquals("Good",result.comment());assertEquals("Synthetic author",result.userName());assertTrue(result.isMine());verify(media).replaceAttachments(eq(owner),eq(result.id()),eq(List.of(image)));}
 @Test void publicDisplayFallbackDoesNotModifyUserProfile(){var author=new User();author.setId(owner);author.setFullName("");when(users.findById(owner)).thenReturn(Optional.of(author));when(eligibility.hasCompletedBookingForAccommodation(owner,booking,stay)).thenReturn(true);assertEquals("Guest",service.create(owner,stay,new CreateReviewRequest(booking,5,"",List.of())).userName());assertEquals("",author.getFullName());}
 @Test void foreignOwnerCannotEditOrDelete(){var r=new Review();r.setId(UUID.randomUUID());r.setUserId(UUID.randomUUID());when(rows.lockById(r.getId())).thenReturn(Optional.of(r));assertThrows(BusinessException.class,()->service.update(owner,r.getId(),new UpdateReviewRequest(3,"Updated",List.of())));assertThrows(BusinessException.class,()->service.delete(owner,r.getId()));verify(media,never()).replaceAttachments(any(),any(),any());verify(rows,never()).delete(any());}
}
